use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { println ! ("🚀 Simple SPARQL-like Query Engine") ; println ! ("==================================\\n") ; println ! ("📚 Loading knowledge base...") ; let content = fs :: read_to_string ("rustc_lmdfb_knowledge_base.owl") ? ; let mut triples = Vec :: new () ; let mut predicates = HashMap :: new () ; for line in content . lines () { if let Some (triple) = parse_triple (line) { triples . push (triple . clone ()) ; * predicates . entry (triple . 1 . clone ()) . or_insert (0) += 1 ; } } println ! ("📊 Knowledge Base Loaded:") ; println ! ("   Triples: {}" , triples . len ()) ; println ! ("   Unique predicates: {}" , predicates . len ()) ; println ! ("\\n🔍 Running Queries:") ; let components = triples . iter () . filter (| (_ , p , o) | p == "rdf:type" && o == "lmdfb:RustcComponent") . count () ; println ! ("1. Components: {}" , components) ; let levels = triples . iter () . filter (| (_ , p , _) | p == "lmdfb:hasLevel") . count () ; println ! ("2. Level assignments: {}" , levels) ; let patterns = triples . iter () . filter (| (_ , p , _) | p == "lmdfb:hasSemanticPattern") . count () ; println ! ("3. Semantic patterns: {}" , patterns) ; let mut pred_vec : Vec < _ > = predicates . into_iter () . collect () ; pred_vec . sort_by (| a , b | b . 1 . cmp (& a . 1)) ; println ! ("\\n📈 Top 10 Predicates:") ; for (i , (pred , count)) in pred_vec . iter () . take (10) . enumerate () { println ! ("   {}. {} ({})" , i + 1 , pred , count) ; } println ! ("\\n✅ Query Engine Ready!") ; println ! ("   Knowledge base successfully analyzed") ; Ok (()) }
}